# >>> CHOICES
_choice_recipient() {
    {
        if [[ -n "$SSH_AUTH_SOCK" ]] && command -v ssh-add >/dev/null; then
            ssh-add -L 2>/dev/null | gawk 'NF >= 2 { print $1 " " $2 "\tSSH agent key" }'
        fi
        local file
        for file in "$HOME"/.ssh/*.pub; do
            [[ -f "$file" ]] || continue
            gawk -v name="${file##*/}" 'NF >= 2 { print $1 " " $2 "\t" name }' "$file"
        done
        for file in "$HOME"/.config/age/keys.txt "$HOME"/.age/keys.txt; do
            [[ -f "$file" ]] || continue
            gawk -v name="${file##*/}" '/^# public key: / { print $4 "\t" name }' "$file"
        done
    } | gawk -F'\t' '!seen[$1]++'
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
